CREATE TABLE IF NOT EXISTS banks(id INTEGER PRIMARY KEY AUTOINCREMENT,slug TEXT UNIQUE NOT NULL,name TEXT NOT NULL,short_name TEXT NOT NULL,color TEXT NOT NULL DEFAULT '#075a4c',health_score REAL NOT NULL DEFAULT 0,summary TEXT NOT NULL DEFAULT '',active INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS financial_metrics(id INTEGER PRIMARY KEY AUTOINCREMENT,bank_id INTEGER NOT NULL,period TEXT NOT NULL,assets REAL,deposits REAL,profit REAL,capital_adequacy REAL,liquidity REAL,npl REAL,status TEXT NOT NULL DEFAULT 'draft',source_url TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(bank_id) REFERENCES banks(id));
CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY AUTOINCREMENT,bank_id INTEGER NOT NULL,effective_date TEXT NOT NULL,savings_rate REAL,loan_rate REAL,transfer_fee REAL,minimum_balance REAL,status TEXT NOT NULL DEFAULT 'draft',source_url TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(bank_id) REFERENCES banks(id));
CREATE TABLE IF NOT EXISTS sources(id INTEGER PRIMARY KEY AUTOINCREMENT,bank_id INTEGER NOT NULL,url TEXT NOT NULL,source_type TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,FOREIGN KEY(bank_id) REFERENCES banks(id));
CREATE TABLE IF NOT EXISTS source_checks(id INTEGER PRIMARY KEY AUTOINCREMENT,source_id INTEGER NOT NULL,status TEXT NOT NULL,content_hash TEXT,checked_at TEXT NOT NULL,error TEXT,FOREIGN KEY(source_id) REFERENCES sources(id));
CREATE TABLE IF NOT EXISTS scan_runs(id INTEGER PRIMARY KEY AUTOINCREMENT,started_at TEXT NOT NULL,finished_at TEXT,checked INTEGER DEFAULT 0,changed INTEGER DEFAULT 0,failed INTEGER DEFAULT 0,country_id INTEGER REFERENCES countries(id));
CREATE VIEW IF NOT EXISTS latest_metrics AS SELECT fm.* FROM financial_metrics fm JOIN(SELECT bank_id,MAX(id) id FROM financial_metrics WHERE status='published' GROUP BY bank_id)x ON fm.id=x.id;
CREATE VIEW IF NOT EXISTS latest_products AS SELECT p.* FROM products p JOIN(SELECT bank_id,MAX(id) id FROM products WHERE status='published' GROUP BY bank_id)x ON p.id=x.id;